/* THE FIELD FRAME — one recipe, six wearers.
 *
 * `.input`, `.select-trigger`, `.datepicker-trigger`, `.number-input`,
 * `.taginput` and `.search-input` each draw their own box, and they had drifted:
 * NumberInput answered focus by recolouring its 1px border while every sibling
 * drew a 2px ring, two of them had no hover at all, SearchInput hard-coded
 * --radius-full past --control-radius, and only two turned the ring red when the
 * value was invalid. In one form that reads as six controls from six systems.
 *
 * The recipe every one of them now keeps, in this order:
 *   resting   1px solid var(--input) on var(--background), --control-radius
 *   hover     border-color -> var(--ring)
 *   focus     outline var(--focus-ring), offset --ring-offset
 *   invalid   border-color -> var(--destructive); the ring turns red too
 *   muted     resting border dropped; invalid and focus still show
 *   disabled  opacity 0.5, cursor not-allowed, pointer events KEPT so a
 *             Tooltip can say why
 * Change the recipe here and carry it to all six. */
.input {
  display: block;
  width: 100%;
  height: var(--control-height);
  padding-inline: var(--control-padding-x);
  border-radius: var(--control-radius);
  border: 1px solid var(--input);
  background: var(--background);
  color: var(--foreground);
  /* WHAT DOES NOT FIT IS CUT WITH AN ELLIPSIS, and this is the one wearer of
   * the recipe that was not doing it. A text input scrolls its value by
   * default, so a title longer than the field ended mid-letter — "Community
   * Outreach N" — and nothing on screen said there was more (owner, 2026-08-29).
   * The ellipsis applies while the field is at rest; the moment it takes focus
   * the browser goes back to scrolling, which is what a person editing needs. */
  text-overflow: ellipsis;
  transition: border-color var(--duration-fast);
}
/* Sizes — mirror the button/control scale. */
.input[data-size="sm"] { height: var(--control-height-sm); padding-inline: var(--space-3); font-size: var(--font-sm); }
.input[data-size="lg"] { height: var(--control-height-lg); font-size: var(--control-font-size-lg); }

.input::placeholder { color: var(--muted-foreground); }

/* Native date and time fields: tame the widget so it reads as one of ours. The
 * value is tabular so dd/mm/yyyy and hh:mm do not wobble while typing; the
 * calendar (or clock) glyph sits quiet until hovered — it cannot be recoloured,
 * only dimmed.
 *
 * `time` joined `date` here when <TimeInput> was folded back into this
 * component (2026-08-30): it was 21 lines of code that rendered the same
 * `<input class="input">` this file already styles, and carried its own copy of
 * these three rules with the type swapped. A native input type is a value of
 * `type`, not a component. */
.input[type='date'],
.input[type='time'] {
  font-family: inherit;
  font-variant-numeric: tabular-nums;
}
.input[type='date']::-webkit-calendar-picker-indicator,
.input[type='time']::-webkit-calendar-picker-indicator {
  /* color-scheme flips the native glyph light in dark mode; 0.45 left it too
   * faint there, so it rests a touch stronger and goes full on interaction. */
  opacity: 0.6;
  cursor: pointer;
}
.input[type='date']:hover::-webkit-calendar-picker-indicator,
.input[type='date']:focus-visible::-webkit-calendar-picker-indicator,
.input[type='time']:hover::-webkit-calendar-picker-indicator,
.input[type='time']:focus-visible::-webkit-calendar-picker-indicator {
  opacity: 1;
}

/* Browsers repaint autofilled fields with their own grey/yellow background and
 * dark text, ignoring our tokens — that's what reads as a "grey" login field.
 * The inset box-shadow re-covers the fill with --background; the long transition
 * holds it so the native colour never flashes through. */
.input:-webkit-autofill,
.input:-webkit-autofill:hover,
.input:-webkit-autofill:focus {
  -webkit-text-fill-color: var(--foreground);
  -webkit-box-shadow: 0 0 0 100px var(--background) inset;
  caret-color: var(--foreground);
  transition: background-color 100000s ease-out 0s;
}

.input:hover:not(:disabled) { border-color: var(--ring); }
/* On a --muted surface the white fill separates the field; drop the resting
 * border (invalid + focus outline still show). */
.input[data-surface="muted"]:not([aria-invalid="true"]),
.input[data-surface="muted"]:not([aria-invalid="true"]):hover:not(:disabled) { border-color: transparent; }
.input:disabled {
  opacity: var(--disabled-opacity);
  cursor: not-allowed;
}
.input[aria-invalid="true"] {
  border-color: var(--destructive);
}
.input[aria-invalid="true"]:focus-visible {
  outline-color: var(--destructive);
}

import './Input.css'
import type { ComponentPropsWithRef } from 'react'
import { cn } from '../lib/cn'

/* ComponentPropsWithRef, not InputHTMLAttributes: React 19 passes `ref` as an
 * ordinary prop, but only if the prop type says so. It did not, so no consumer
 * could focus or select the field programmatically, and every dialog that wanted
 * to reached for `autoFocus` instead. `ref` rides along in `...rest`. */
type Props = Omit<ComponentPropsWithRef<'input'>, 'size'> & {
  /** The field failed validation. A STATE, not a style: it turns the border and
   *  gives `<Field>` the hook that ties the error message to this control, so
   *  the reason is read out as part of the field. Colouring a border red by hand
   *  produces the look without the announcement. */
  invalid?: boolean
  /** Which surface the field sits on. On `muted` (a page/PageHeader) the border
   *  is dropped since the white fill separates it; `base` (default, a white card
   *  or form) keeps the border. Invalid + focus stay visible on both. */
  surface?: 'base' | 'muted'
  /** Control height: sm / md (default) / lg — matches the button/control scale. */
  size?: 'sm' | 'md' | 'lg'
}

/**
 * The single-line field: label, invalid state and the shared control tokens.
 * Native types ride on `type` — `date` and `time` are styled here rather than
 * wrapped in components of their own. A screen never renders a bare input.
 */
export function Input({ invalid, size, surface = 'base', className, ...rest }: Props) {
  return (
    <input
      className={cn('input', className)}
      data-size={size}
      aria-invalid={invalid || undefined}
      data-surface={surface}
      {...rest}
    />
  )
}
